1	{% extends "base.html" %}
2	{% block title %}{{ observation.pupil }} on {{ observation.observed_on }}{% endblock %}
3	{% block content %}
4	<h1>{{ observation.pupil }}</h1>
5	<p><strong>{{ observation.observed_on }}</strong> · {{ observation.get_mood_display }} · recorded by {{ observation.author.get_full_name|default:observation.author.username }}</p>
6	<div>{{ observation.body|linebreaks }}</div>
7	{% if observation.agreed_action %}
8	<h2>Agreed action</h2>
9	<div>{{ observation.agreed_action|linebreaks }}</div>
10	{% else %}
11	<p><em>No action agreed.</em></p>
12	{% endif %}
13	<p><a href="{% url 'observation_edit' observation.pk %}">Edit</a> · <a href="{% url 'observation_list' %}">Back to list</a></p>
14	{% endblock %}
